import{_ as a,o as t,c as e,ai as o}from"./chunks/framework.DAbPic9L.js";const d=JSON.parse('{"title":"筱问集注-我是谁","description":"","frontmatter":{},"headers":[],"relativePath":"mybook/xiao-wen-ji-zhu/wo-shi-shui.md","filePath":"mybook/xiao-wen-ji-zhu/wo-shi-shui.md","lastUpdated":1787215730000}'),r={name:"mybook/xiao-wen-ji-zhu/wo-shi-shui.md"};function i(s,p,n,_,b,h){return t(),e("div",null,[...p[0]||(p[0]=[o('<h1 id="筱问集注-我是谁" tabindex="-1">筱问集注-我是谁 <a class="header-anchor" href="#筱问集注-我是谁" aria-label="Permalink to &quot;筱问集注-我是谁&quot;">​</a></h1><p>文/晨风不可依米</p><br><p>你是谁，这个问题本身没有任何意义。无论怎样抽象概括、具体描述，没有任何语言能够说得明白。无需概括描述，你就是你。</p><br><p>或许你看过或了解过心理学的三个基本问题：我是谁，我从哪里来，我要到哪里去。但我想告诉你，从一出生，这三个问题的答案就早已出现。你出生后会有名字，你就是那个名字代号的存在；你来自于精子和卵子在子宫中结合发育而来的个体，并结束于生命个体自我终结的湮灭过程。你并不是为了某一目的或使命而来，你也仅仅是生命存在的不同形式状态物而已。</p><br><p>这个世界没有生命轮回概念或事实，因此鬼神论这些相关的衍生物也不会存在。所谓鬼神，不过是由人神化或鬼化的话题，也是人制造精神恐惧的手段。很多人把不可知领域抽象概括为灵异范畴，又嫁接在鬼神论的精神基础上，觉得玄学又合理；但这种想法是不可取的。这就像一个哲学问题：是帆动，是风动，还是心动？其最终解释权在于差异性生命个体上。而绝大多数生命个体都是从自身出发，因此导致一种认知堆积的社会现象，并形成对某个话题的共识存在。但这种共识存在是否足够客观概括，只需要看三点：一是逻辑状态推导，二是事实普遍存在，三是未有意识附着；这也是衡量是否科学的唯一标准。</p><br><p>这个社会，很多事物都存在或关联&quot;科学&quot;二字，但那些所谓的&quot;科学&quot;并不是科学，而是共识存在的自我合理化；简单来讲，就是为某些行为事物而存在的糊弄。真正的科学，它是有所规律的，是严谨有效的状态描述；更深层次的来讲，它就是一个事物叠加态。一个事物存在由多个事物叠加态所构成，但不同种类、数量、排布等方式所能影响事物存在的状态也不一样，存在概率性；同时所能逻辑推导的可能态结果是确切的；当然，那些无法理解的认知存在得归为不可知领域范畴，值得人们在未来继续探究深入。</p><br><p>生命存在的形式绝大多数由原子和电子所聚合构成；而原子具有束缚态，电子具有离散态。正因为这两种状态相互存在，我们的生命才如此具有活力色彩。死亡并不是生命存在的终点，它不过是生命存在的湮灭过程的一个特殊状态；即机能不在或尸骨不存。</p><br><p>生命，并不是人类所能概括的存在；而是所有的一切对象都具有生命。我们能看得见，摸得着，或者观测感觉得到的，都是生命存在的不同形式。只不过人类作为食物链上的高端者，在适者生存的黑森林法则中蔑视弱小或死物等生命存在的不同形式而已。生命存在的过程，本是我自化生，自我终亡，随处可见的存在现象。而作为人，我们无法决定我们的出身，但我们可以通过意识以及行为决定未来所要选择的路，而且这一系列过程只能通过自己亲眼见证。</p><br><p>在我们的成长中，我们会逐渐地认识到这个世界的基本规律：化学物质不变论的形态世界、数学结构式计算的推理法则。在未来的某个醒悟时刻，我们会逐渐地明白自身是个怎么的存在个体，也对未来将要前行的路决情断疑、利己权衡、理性前行，会更加深入理解自己的人生。当你已然明白这两种基本规律之后，你的未来是可以被观测推理得到的；并逐渐唤醒本能的通感趋利避害，甚至运势掌握在自己的手中<span class="text-red">(天所赋为命，运操之在你)</span>。</p><br><p>从概念上讲，我们都是人；而人的一生，大抵都是在重新认识、理解这个聚变的新世界，并在这个世界的新环境努力存活，探索那条利己的生存法则。在这一过程中，我们对外界存在兴趣，并在时间累积中执着专注，从而构建理论，然后验证结果；从反复复杂的过程中提炼出简要方程，最终成为领域专家。这些流程现象在宏观层面上，从经历中转换为经验，从重组构建中再次优化到简单。</p><br><p>因此，复杂事物由简单事物构成，组织整体由要素部分构成。从微观层面上，所谓人不过是由原子组成，并在化学物质不变论下不断重组机体，内聚的化学能提供了热驱动，生命也因此交替存在；我们能感知、能思考、能有所灵感，这些充其量不过是电化学信号的反复碰撞而泛化的具体表现。</p><br><p>我们来自于多样元素物质所凝聚的结果，而元素物质的起源和传播由化学能的聚变所演化。在宇宙中，我们是一簇簇松散的尘埃，生命的脆弱和仞性有所体现；同样，星辰是一团团内聚的结块，能量的引力和驱动叹为观止。而在时间历史的演化过程中，我们曾是星辰构建的要素部分，星辰坍塌挥洒的物质元素也曾是人机体构建的要素部分；因此，我们即星辰，星辰即我们。这也正是远古时期人探索宇宙星辰与探索自我演化的交聚点。</p><br><p>时代的更迭千古不变，宇宙的演化从一而终；生命的本质是内聚的热驱动，意识不过是电化学信号的反复碰撞，记忆不过是电子元素在高维时间的场域流转。</p><br><p>那么，世俗的那点约定俗成，纯粹是自我感觉良好的感性认识。生命的岁月痕迹，早已注定我们如尘土飞扬，而相互碰撞的场域与内聚驱动的能量才是生命意义的存在。我们不过一粒尘土，在化学物质层面上不会消失，不被创造，只是以不同的物质元素存在而已。死亡并不可怕，无非是人机体构建的要素物质失去了化学能的热驱动而已；在时间历史演化过程中，原子物质重组后，我们以不同机体的存在形式仍旧再次归来；只不过，所丧失的电子元素(记忆)在互斥过程中遗失。</p><br><p>所以，人的生死不值得一提，甚至得看淡；但在重组之后再次归来，请务必在睁眼醒来那一刻保持理性，你终将理解、掌握，并极致发挥属于自己的那一份特殊；你会像一缕清风，无孔不入，经物不觉地飘荡于世界的每一处角落，甚至窥见这个世界的全貌模样。</p>',28)])])}const c=a(r,[["render",i]]);export{d as __pageData,c as default};
